#!/usr/bin/env bash\n\nset -euo pipefail\n\n# Mock rationale: This test builds the Docker image locally, runs the container with a known input JSON,\n# captures the output, and compares it to the expected string. No external network calls are made.\n\n# Create a temporary directory for the test\nTMPDIR=$(mktemp -d)\ncleanup() { rm -rf "$TMPDIR"; }\ntrap cleanup EXIT\n\n# Write the input JSON\ncat > "$TMPDIR/input.json" <<'EOF'\n{\n  "max_weight": 10,\n  "items": [\n    {"name": "Water Bottle", "weight": 3, "value": 8},\n    {"name": "Canned Food", "weight": 2, "value": 5},\n    {"name": "First‑Aid Kit", "weight": 5, "value": 9},\n    {"name": "Flashlight", "weight": 1, "value": 3},\n    {"name": "Map", "weight": 1, "value": 2}\n  ]\n}\nEOF\n\n# Expected output (exact match)\nread -r -d '' EXPECTED <<'EOS'\nSelected items:\n- Water Bottle (weight: 3, value: 8)\n- Canned Food (weight: 2, value: 5)\n- Flashlight (weight: 1, value: 3)\n- Map (weight: 1, value: 2)\nTotal weight: 7\nTotal value: 18\nEOS\n\n# Build the Docker image\ndocker build -t nightly-survival-packer-test . > /dev/null\n\n# Run the container, mounting the input file\nOUTPUT=$(docker run --rm -v "$TMPDIR/input.json:/data/input.json" nightly-survival-packer-test /data/input.json)\n\n# Compare output\nif [[ "$OUTPUT" == "$EXPECTED" ]]; then\n  echo "Test passed."\n  exit 0\nelse\n  echo "Test failed. Expected:"\n  echo "$EXPECTED"\n  echo "Got:"\n  echo "$OUTPUT"\n  exit 1\nfi\n
